import {ToolRegistry} from './registry.js';

describe('ToolRegistry static validation', () => {
  // @spec specs/hal-engine-tool-input-validation/spec.md#8
  it('keeps the registered static schema across ten calls after its definition changes', async () => {
    const registry = new ToolRegistry();
    const definition = {
      name: 'weather',
      description: 'Weather by location',
      inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
    };
    registry.register(definition, async input => JSON.stringify(input));
    definition.inputSchema = {
      type: 'object',
      properties: {location: {type: 'number'}},
      required: ['location'],
    };

    const results = [];
    for (let call = 0; call < 10; call++) {
      results.push(await registry.execute('weather', {location: 'Berlin'}));
    }

    expect(results).toEqual(Array.from({length: 10}, () => ({result: '{\"location\":\"Berlin\"}'})));
  });
});
EOF
